// Safe abstraction over raw-ish indexing logic (no unsafe needed here,
// but shows the wrapper discipline).
struct Grid {
    cells: Vec<i32>,
    width: usize,
}

impl Grid {
    fn new(width: usize, height: usize) -> Self {
        Self { cells: vec![0; width * height], width }
    }

    /// Returns None for out-of-bounds — callers cannot corrupt memory.
    fn get(&self, x: usize, y: usize) -> Option<i32> {
        if x >= self.width {
            return None;
        }
        self.cells.get(y * self.width + x).copied()
    }
}

fn main() {
    let grid = Grid::new(3, 2);
    println!("{:?} {:?}", grid.get(2, 1), grid.get(9, 9));
}

