struct Grid {
    cells: Vec<i32>,
    width: usize,
    height: usize,
}

impl Grid {
    fn new() -> Self {
        Self { cells: (1..=6).collect(), width: 3, height: 2 }
    }
    fn get(&self, x: usize, y: usize) -> Option<i32> {
        if x >= self.width || y >= self.height {
            return None;
        }
        self.cells.get(y * self.width + x).copied()
    }
}

fn main() {
    let g = Grid::new();
    println!("{:?} {:?}", g.get(2, 1), g.get(3, 0));
}
